declare(strict_types=1);$pageTitle='Database Manager';$topNavSection='control';$BODY_CLASS='hub-page';require __DIR__.'/ui_bootstrap.php';$migrations=$uiRepository->rows('database_manager');$backups=$uiRepository->rows('backup_health');$installations=$uiRepository->rows('installations');$configurationBackups=[];foreach($backups as$row){$scope=is_array($row['scope']??null)?$row['scope']:[];if(($scope['kind']??'')==='configuration')$configurationBackups[]=$row;}include __DIR__.'/tmpl/head.html';if(!$embedded)include __DIR__.'/tmpl/navbar.php';?>
<main class="almsivi-page<?php echo $embedded?' embedded':''; ?>"><header class="almsivi-page-header"><div><h1>Database Manager</h1><p>Installation Configuration Backups are bounded and secret-free. Core Profiles and NPC assignments are included.</p></div><span class="almsivi-badge">Schema <?php echo almsivi_ui_h($migrations[0]['version']??'unknown'); ?></span></header><?php if(isset($_GET['status'])): ?><div class="almsivi-status">Database operation completed.</div><?php endif; ?>
<section class="almsivi-grid"><article class="almsivi-card"><h2>Create configuration backup</h2><form method="post" action="<?php echo almsivi_ui_h($managementBasePath); ?>/forms/configuration-backup"><input type="hidden" name="_csrf" value="<?php echo almsivi_ui_h($csrf); ?>"><label>Installation<select name="installation_id"><?php foreach($installations as$row): ?><option value="<?php echo almsivi_ui_h($row['installation_id']); ?>"><?php echo almsivi_ui_h($row['display_name']); ?></option><?php endforeach; ?></select></label><label>Type Backup to confirm<input name="confirm" required autocomplete="off"></label><div class="almsivi-actions"><button type="submit">Create Backup</button></div></form></article>
<article class="almsivi-card"><h2>Restore configuration backup</h2><?php if($configurationBackups===[]): ?><p class="almsivi-empty">No configuration backups are available.</p><?php else: ?><form method="post" action="<?php echo almsivi_ui_h($managementBasePath); ?>/forms/configuration-restore"><input type="hidden" name="_csrf" value="<?php echo almsivi_ui_h($csrf); ?>"><label>Destination installation<select name="installation_id"><?php foreach($installations as$row): ?><option value="<?php echo almsivi_ui_h($row['installation_id']); ?>"><?php echo almsivi_ui_h($row['display_name']); ?></option><?php endforeach; ?></select></label><label>Stored backup<select name="backup_id"><?php foreach($configurationBackups as$row): ?><option value="<?php echo almsivi_ui_h($row['backup_id']); ?>"><?php echo almsivi_ui_h($row['created_at'].' · '.$row['state']); ?></option><?php endforeach; ?></select></label><label>Type Restore to confirm<input name="confirm" required autocomplete="off"></label><div class="almsivi-actions"><button type="submit">Restore Backup</button></div></form><?php endif; ?></article></section>
<section class="almsivi-card"><h2>Stored configuration backups</h2><?php if($configurationBackups===[]): ?><p class="almsivi-empty">No configuration backups exist yet.</p><?php else: ?><div class="almsivi-grid"><?php foreach($configurationBackups as$row): ?><article><strong><?php echo almsivi_ui_h($row['created_at']); ?></strong><p class="almsivi-muted"><?php echo almsivi_ui_h($row['state']); ?> · <?php echo almsivi_ui_h($row['byte_count']); ?> bytes · format <?php echo almsivi_ui_h($row['format_version']); ?></p><a class="btn-base" href="<?php echo almsivi_ui_h($managementBasePath); ?>/exports/backups/<?php echo almsivi_ui_h($row['backup_id']); ?>.json">Download backup</a></article><?php endforeach; ?></div><?php endif; ?></section><section class="almsivi-card"><h2>Applied schema migrations</h2><?php almsivi_ui_table($migrations,'No schema migrations are recorded.'); ?></section></main><?php include __DIR__.'/tmpl/footer.html'; ?>
